#[test]
fn central_directory_io_error_is_preserved() {
    use std::io::{self, Seek, SeekFrom};
    struct FallibleReader { cursor: Cursor<Vec<u8>>, central: u64, failed: bool }
    impl Read for FallibleReader {
        fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
            if self.cursor.position() == self.central && buf.len() == 46 && !self.failed {
                self.failed = true;
                return Err(io::Error::new(io::ErrorKind::Other, "review transient I/O error"));
            }
            self.cursor.read(buf)
        }
    }
    impl Seek for FallibleReader {
        fn seek(&mut self, from: SeekFrom) -> io::Result<u64> { self.cursor.seek(from) }
    }
    let cursor = archive(stored());
    let central = ZipArchive::new(cursor.clone()).unwrap().central_directory_start();
    let result = ZipArchive::new(FallibleReader { cursor, central, failed: false });
    assert!(matches!(result, Err(zip::result::ZipError::Io(ref e)) if e.to_string() == "review transient I/O error"), "I/O error was discarded");
}
